package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ArtLiveExamWesternClassicBank2 {
    private const val T = "බටහිර සම්භාව්‍ය කලාව (මිසර, ග්‍රීක, රෝම, පුනරුද, බැරොක්)"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("පැරණි මිසර කලාවේ ගල් පුවරු මත වියළි බිතුසිතුවම් ඇඳීමේදී භාවිත කළ 'රූපාක්ෂර ලේඛන ක්‍රමය' හඳුන්වන්නේ කුමන නමින්ද?", "හයිරොග්ලිෆික්ස් (Hieroglyphics)", "බ්‍රාහ්මී අක්ෂර", "කියුනිෆෝම් අක්ෂර", "ලතින් අක්ෂර", "රූප සංකේතවලින් ලියන හයිරොග්ලිෆික්ස් අක්ෂර මිසර සොහොන් ගැබ් සිතුවම් සමඟම ඒකාබද්ධව පැවතුණි."),
        q("මිසර කලාවේ සුප්‍රකට 'නාමර් පුවරුව' (Palette of Narmer) වැදගත් වන්නේ කුමන ඓතිහාසික හා කලාත්මක හේතුව නිසාද?", "මිසරය එක්සත් කිරීමේ මුල් කැටයම", "ලොව මුල්ම තෙල් සායම් සිතුවම", "ග්‍රීක ඔලිම්පික් ක්‍රීඩා පුවරුව", "පුරාණ ගල් යුගයේ චිත්‍ර ලේඛනය", "අඩු උන්නත කැටයමින් රූප තීරු ලෙස බෙදා නාමර් රජුගේ ජයග්‍රහණය මෙහි කැටයම් කර ඇත."),
        q("මිසර සොහොන් ගැබ් සිතුවම්වල 'සමූහ නර්තන හෝ සේවක රූප' සමහර විට රජුට වඩා නිදහසේ ස්වභාවිකව ඇඳ ඇත්තේ ඇයි?", "සේවකයන් චලන ඉරියව්වලින් ඇඳීම නිසා", "පාරාවෝවරුන් රූපවලට තහනම් කිරීම නිසා", "බිත්ති බදාමය ඉරිතලා තිබීම නිසා", "වර්ණ මිශ්‍ර කිරීමට අපහසු වූ නිසා", "නෙබමුන් සොහොන් ගැබේ දඩයම් හා නැටුම් සිතුවම්වල මිනිස් හා සත්ව රූප අලංකාර චලන ලාලිත්‍යයක් පෙන්වයි."),
        q("මෙසපොතේමියානු (සුමේරියානු, බැබිලෝනියානු, ඇසිරියානු) වාස්තු කලාවේ ප්‍රධාන පූජනීය පියගැටපෙළ කුළුණ හඳුන්වන්නේ කෙසේද?", "සිගුරැට් (Ziggurat)", "පාතිනන්", "ස්තූපය", "පිරමීඩය", "අව්වේ වේලූ මැටි ගඩොලින් උස් වේදිකා මත පියගැට ලෙස ඉදි කළ දේවාල සිගුරැට් නම් වේ."),
        q("පුරාණ ඇසිරියානු රාජ මාලිගා දොරටු ආරක්ෂා කිරීමට නෙළා තිබූ පියාපත් ඇති ගොනෙකුගේ සිරුර හා මිනිස් හිස සහිත දැවැන්ත මූර්තිය කුමක්ද?", "ලමාසු (Lamassu)", "ස්පින්ක්ස්", "ගජසිංහ", "සෙන්ටෝර්", "පාද පහක් සහිතව කැටයම් කළ ලමාසු ප්‍රතිමා ඉදිරියෙන් සිටින ලෙසත් පැත්තෙන් ඇවිදින ලෙසත් පෙනේ."),
        q("බැබිලෝනියාවේ දීප්තිමත් නිල් ඔප දැමූ ගඩොල්වලින් සිංහ, ගොන් හා මකර රූප සහිතව නිමවූ ප්‍රසිද්ධ දොරටුව කුමක්ද?", "ඉෂ්තාර් දොරටුව (Ishtar Gate)", "සාංචි තොරණ", "බ්‍රැන්ඩන්බර්ග් දොරටුව", "ශාන්ත පීතර දොරටුව", "නෙබුකද්නෙසර් රජු තැනූ ඉෂ්තාර් දොරටුව ඔප දැමූ සෙරමික් ටයිල් කලාවේ පුරාණ විස්මයකි."),
        q("ග්‍රීක මූර්ති කලාවේ මුල් 'ආකේයික්' (Archaic) යුගයේ සෘජුව සිටගත් තරුණ පුරුෂ ප්‍රතිමා හඳුන්වන්නේ කුමන නමින්ද?", "කූරෝස් (Kouros)", "කෝරේ", "ඩේවිඩ්", "මොනාලිසා", "මිසර ආභාසය සහිත වුවද නිරුවතින් හා කූරෝස් සිනහවෙන් යුතුව ග්‍රීකයන් ස්වාධීන මූර්ති කලාව ඇරඹීය."),
        q("ග්‍රීක 'කූරෝස්' සහ 'කෝරේ' මූර්තිවල මුහුණුවල දක්නට ලැබෙන විශේෂිත මද සිනහව හඳුන්වන්නේ කෙසේද?", "ආකේයික් සිනහව (Archaic Smile)", "මොනාලිසා සිනහව", "බැරොක් සිනහව", "ඩොරික් සිනහව", "මූර්තියට ජීව ගුණයක් ලබා දීම සඳහා තොල් දෙක මඳක් ඉහළට එසවූ මෙම සිනහව මුල් ග්‍රීක ලක්ෂණයකි."),
        q("හෙලනිස්තික ග්‍රීක මූර්ති කලාවේ මානව වේදනාව හා පීඩනය උපරිමයෙන් නිරූපණය කරන සර්පයන් වෙළුණු පූජක පවුලේ ප්‍රතිමාව කුමක්ද?", "ලැකූන් සහ ඔහුගේ පුතුන්", "ඩිස්කොබොලස් ක්‍රීඩකයා", "බොටිචෙලිගේ වීනස් උපත", "රැෆායෙල්ගේ ඇතන්ස් පාසල", "පුනරුද යුගයේ මයිකල් ආන්ජලෝ කෙරෙහි පවා දැඩි ලෙස බලපෑම් කළ නාට්‍යමය හෙලනිස්තික මූර්තියකි."),
        q("ලූවර් කෞතුකාගාරයේ ඇති දෑත් අහිමි ලෝක ප්‍රකට ග්‍රීක හෙලනිස්තික කිරිගරුඬ ප්‍රතිමාව කුමක්ද?", "වීනස් ඩි මිලෝ ප්‍රතිමාව", "නෙෆර්ටිටි රැජිනගේ උඩුකය", "ෆ්ලෝරන්ස් ඩේවිඩ් ප්‍රතිමාව", "සමොත්‍රේස් හි පියාපත් නයිකි", "සර්පිලාකාර ඇඹරුණු දේහ විලාසය හා සිහින් ඇඳුම් රැලි වීනස් ඩි මිලෝ හි කැපී පෙනේ."),
        q("රෝම අධිරාජ්‍යයේ හේඩ්‍රියන් අධිරාජ්‍යයා විසින් සම්පූර්ණ කරන ලද වහල මුදුනේ 'ඕකියුලස්' (Oculus) නම් වෘත්තාකාර ආලෝක විවරයක් ඇති දේවාලය කුමක්ද?", "පැන්තියන් දේවාලය (The Pantheon)", "පාතිනන් දේවාලය", "කොලෝසියම", "නොට්‍ර-ඩෑම්", "ආධාරක කුළුණු නොමැතිව තැනූ ලොව විශාලතම සවිබල නොගැන්වූ කොන්ක්‍රීට් ගෝලාකාර වහලය මෙහි වේ."),
        q("පුරාණ රෝම ආලේඛ්‍ය මූර්ති කලාව (Roman Portraiture) ග්‍රීක සම්භාව්‍ය මූර්තිවලින් වෙනස් වන ප්‍රධාන ගුණාංගය කුමක්ද?", "වයස්ගත රැලි හා සැබෑ මුහුණු නෙළීම", "පරිපූර්ණ තරුණ මුහුණු පමණක් නෙළීම", "කළු තීන්ත මුළුමනින්ම ආලේප කිරීම", "සත්ව හිස් මිනිස් සිරුරට සවි කිරීම", "වයස්ගත ජ්‍යෙෂ්ඨයන්ගේ ප්‍රඥාව හා අත්දැකීම් ගෞරවයෙන් දැක්වීමට රෝමවරු අතිශය යථාර්ථවාදී මුහුණු නෙළූහ."),
        q("රෝමයේ කොන්ස්තන්තීනු, ටයිටස් හා සෙප්ටිමියස් සෙවේරස් වැනි අධිරාජ්‍යයන්ගේ යුද ජයග්‍රහණ සැමරීමට ඉදි කළ වාස්තු නිර්මාණ වර්ගය කුමක්ද?", "ජයග්‍රාහී ආරුක්කු (Triumphal Arches)", "පියගැට පිරමීඩ ගොඩනැගිලි", "සිගුරැට් මැටි දේවාල", "ගොතික් වීදුරු දෙව්මැදුරු", "විශාල ආරුක්කු දොරටු මත යුද කතා කැටයම් කිරීම රෝම රාජ්‍ය ප්‍රචාරක කලාවේ ප්‍රධාන අංගයක් විය."),
        q("මධ්‍යකාලීන රෝමනෙස්ක් (Romanesque) වාස්තු කලාව ගොතික් කලාවෙන් වෙන් කර හඳුනා ගන්නා ප්‍රධාන ව්‍යුහාත්මක ලක්ෂණය කුමක්ද?", "ඝනකම බිත්ති සහ රවුම් ආරුක්කු", "අතිශය තුනී වර්ණ වීදුරු බිත්ති", "උස් වූ උල් ආරුක්කු සහ පියාඹන ආධාරක", "රන් ආලේපිත ලෝහ වහලවල්", "බලකොටු මෙන් ඝන බිත්ති හා රවුම් රෝම ආරුක්කු රෝමනෙස්ක් දෙව්මැදුරුවල විශේෂ ලක්ෂණයකි."),
        q("ගොතික් ආසන දෙව්මැදුරුවල ඉහළ බිත්ති මත හිරු එළිය වර්ණවත් කර ඇතුළට ගැනීමට යොදාගත් ප්‍රධාන වෘත්තාකාර වීදුරු කවුළුව කුමක්ද?", "රෝස කවුළුව (Rose Window)", "ඕකියුලස් ආලෝක කවුළුව", "බයිසැන්ටයින් මොසැයික් ආරුක්කුව", "පුනරුද ෆ්‍රෙස්කෝ කවුළුව", "ඊයම් පටිවලින් සවි කළ රතු, නිල් හා රන්වන් වීදුරු කැබලිවලින් සෑදූ රෝස කවුළු ෂාට්‍ර් හා නොට්‍ර-ඩෑම්හි වේ."),
        q("පුනරුද යුගයේ චිත්‍ර කලාවේ ප්‍රධාන කේන්ද්‍රස්ථානය වූ ඉතාලි නගරය සහ එහි කලාකරුවන්ට අනුග්‍රහය දැක්වූ ධනවත් පවුල කවුද?", "ෆ්ලෝරන්ස් නගරය සහ මෙඩිචි (Medici) පවුල", "පැරීසිය සහ ටියුඩර් පවුල", "ලන්ඩනය සහ හබ්ස්බර්ග් පවුල", "ඇතන්ස් සහ මෞර්ය පවුල", "මෙඩිචි බැංකුකරුවන්ගේ අනුග්‍රහය නිසා ඩොනටෙලෝ, බොටිචෙලි හා මයිකල් ආන්ජලෝ ෆ්ලෝරන්ස්හි බිහිවූහ."),
        q("මුල් පුනරුද යුගයේ 'ඩේවිඩ්' ලෝකඩ ප්‍රතිමාව නෙළමින් පුරාණ ග්‍රීසියෙන් පසු මුල්ම නිදහස් නිරුවත් ලෝකඩ මූර්තිය තැනුවේ කවුද?", "ඩොනටෙලෝ (Donatello)", "කැරවැජියෝ", "ජොටෝ", "රෙම්බ්‍රාන්ට්", "1440 දී පමණ ඩොනටෙලෝ තැනූ ලෝකඩ ඩේවිඩ් පුනරුද කොන්ට්‍රපොස්ටෝ ඉරියව්ව නැවත පණ ගැන්වීය."),
        q("මුල් පුනරුද චිත්‍ර ශිල්පී 'මසාචියෝ' (Masaccio) විසින් සැන්ටා මරියා නොවෙල්ලා පල්ලියේ ඇඳි 'ශුද්ධ වූ ත්‍රිත්වය' (The Holy Trinity) ප්‍රකට වන්නේ ඇයි?", "ගණිතමය රේඛීය දෘෂ්ටිකෝණය භාවිතය", "මුල්ම කැන්වස් ඇක්‍රිලික් චිත්‍රය වීම", "වියුක්ත ජ්‍යාමිතික රටා පමණක් තිබීම", "ජපන් තීන්ත මාධ්‍යයෙන් ඇඳීම නිසා", "බිත්තිය ඇතුළට ගැඹුරු දෙව්මැදුරු වහලයක් මැවීමේ මායාව මසාචියෝ එහි විද්‍යාත්මකව ගොඩනැගීය."),
        q("ලියනාඩෝ ඩා වින්චිගේ සටහන් පොත්වල ඇති මිනිස් සිරුරේ පරිපූර්ණ ගණිතමය අනුපාත දක්වන ප්‍රකට සටහන කුමක්ද?", "විට්රූවියන් මිනිසා (Vitruvian Man)", "චින්තකයා", "වීනස්ගේ උපත", "රාත්‍රී මුරය", "වෘත්තයක් සහ සමචතුරස්‍රයක් තුළ පිහිටි විට්රූවියන් මිනිසා කලාව හා විද්‍යාවේ එකමුතුව පෙන්වයි."),
        q("පුනරුද සිතුවම් කලාවේ මානව සිරුරු ඉතා සමීප කෝණයකින් කෙටි වී පෙනෙන සේ ඇඳීමේ දෘෂ්ටිමය ශිල්පය කුමක්ද?", "ෆෝෂෝටනිං (Foreshortening)", "ස්ෆුමාටෝ වර්ණ මුසු කිරීම", "පොයින්ටිලිසම් තිත් ක්‍රමය", "ටෙනෙබ්‍රිසම් ආලෝක ක්‍රමය", "පාදයේ සිට හිස දෙසට බලන විට දිගු අවයව කෙටි වී පෙනෙන සේ ඇඳීම ත්‍රිමාණ ගැඹුර තීව්‍ර කරයි."),
        q("වැනීසියානු පුනරුද චිත්‍ර ශිල්පී 'ටිෂන්' (Titian) සහ 'ජියෝජියෝන්' (Giorgione) ප්‍රසිද්ධියට පත් වූයේ කුමන ශෛලීය ගුණාංගය නිසාද?", "පොහොසත් උණුසුම් වර්ණ හා ආලෝක රටා", "කළු-සුදු සමෝච්ඡ රේඛා පමණක් ඇඳීම", "වියුක්ත ජ්‍යාමිතික හැඩතල කැපීම", "පිළිස්සූ මැටි පුවරු සැකසීම", "ෆ්ලෝරන්ස් කලාවේ දැඩි රේඛාව (Disegno) වෙනුවට වැනීසියේ වර්ණ ධනවත් බව හා ස්පර්ශය මුල් විය."),
        q("උතුරු පුනරුදයේ ජර්මානු විශිෂ්ටයා වූ 'ඇල්බ්‍රෙච්ට් ඩියුරර්' (Albrecht Dürer) ලෝක ප්‍රසිද්ධ වූ ප්‍රධාන මුද්‍රණ මාධ්‍ය මොනවාද?", "ලී කැටයම් හා තඹ තහඩු මුද්‍රණ", "සිල්ක් ස්ක්‍රීන් හා ලිතොග්‍රැෆි", "ඩිජිටල් ලේසර් පිටපත් මුද්‍රණ", "බතික් හා ලිනෝ කට් මුද්‍රණ", "'නයිට්වරයා, මරණය සහ යක්ෂයා' වැනි ඩියුරර්ගේ කැටයම් මුද්‍රණ යුරෝපය පුරා විශාල කීර්තියක් දිනීය."),
        q("උතුරු පුනරුදයේ නෙදර්ලන්ත ශිල්පී 'පීටර් බෲගල්' (Pieter Bruegel the Elder) සිතුවම් කළ ප්‍රධාන තේමාව කුමක්ද?", "ගැමි උත්සව, සෘතු හා හිම ක්‍රීඩා", "රෝම අධිරාජ්‍යයන්ගේ ආලේඛ්‍ය රූප", "මිසර දේව කතා හා සොහොන් ගැබ්", "වැනීසියානු රාජ මාලිගා භෝජන", "සාමාන්‍ය ගම්මාන ජීවිතය ඉහළ සිට බලන පුළුල් භූ දර්ශනයක අලංකාර ලෙස බෲගල් සිතුවම් කළේය."),
        q("පුනරුද සමතුලිතතාව බිඳ දමමින් අතිශයින් දිගු කළ ශරීර අවයව, ඇඹරුණු ඉරියව් හා කෘත්‍රිම වර්ණ යොදාගත් පශ්චාත් පුනරුද ශෛලිය කුමක්ද?", "මැනරිසම් (Mannerism)", "ඩොරික් ශෛලිය", "යථාර්ථවාදය", "අවමවාදය", "පාමිජියානිනෝ හා එල් ග්‍රෙකෝ වැනි මැනරිස්ට් ශිල්පීහු සම්භාව්‍ය අනුපාත වෙනුවට අසාමාන්‍ය ලාලිත්‍යයක් මැවූහ."),
        q("මැනරිසම් යුගයේ සිටි 'එල් ග්‍රෙකෝ' (El Greco) ශිල්පියාගේ සිතුවම් පහසුවෙන් හඳුනාගත හැකි ලක්ෂණය කුමක්ද?", "ඉහළට ඇදුණු දිගැති සිරුරු හා ආලෝකය", "ඉතා කෙටි හා මහත චතුරස්‍ර රූප", "පැතලි රතු පසුබිමක කහ තීරු රටා", "වියුක්ත කළු-සුදු තිත් මෝස්තර", "'ඔර්ගාස් සිටුවරයාගේ භූමදානය' හා 'ටොලිඩෝ දසුන' එල් ග්‍රෙකෝගේ ගුප්ත ආධ්‍යාත්මික ශෛලිය පෙන්වයි."),
        q("බැරොක් චිත්‍ර කලාවේ මුළු යුරෝපයම ප්‍රකට වූ ෆ්ලෙමිෂ් ශිල්පී 'පීටර් පෝල් රූබන්ස්ගේ' (Rubens) සිතුවම්වල විශේෂත්වය කුමක්ද?", "පිරිපුන් මාංශල රූප, විකර්ණ චලනය හා උණුසුම් දීප්තිමත් වර්ණ", "සුදුමැලි පැතලි ජ්‍යාමිතික හැඩ", "කළු තීන්ත රේඛා පමණක් තිබීම", "මිනිස් රූප කිසිවක් නොමැති වීම", "රූබන්ස්ගේ විශාල කැන්වස් චිත්‍ර බැරොක් කලාවේ ජවය හා චලනය ඉතා ප්‍රබලව පෙන්වයි."),
        q("රෙම්බ්‍රාන්ට් වෑන් රිජ්න් විසින් වසර ගණනාවක් පුරා 100කට ආසන්න ප්‍රමාණයක් නිර්මාණය කළ විශේෂිත චිත්‍ර වර්ගය කුමක්ද?", "තමන්ගේම ආත්ම-ආලේඛ්‍ය සිතුවම්", "යුද නැව් හා සාගර දසුන්", "නිශ්චල පලතුරු බඳුන් සිතුවම්", "පූජනීය ග්‍රීක දේව කතා", "තරුණ වියේ සිට වයස්ගත මහලු විය දක්වා තම මානසික හා භෞතික වෙනස ඔහු අවංකව සිතුවම් කළේය."),
        q("ලන්දේසි ස්වර්ණමය යුගයේ (17 වන සියවස) ඉතා ජනප්‍රිය වූ මිනිස් ජීවිතයේ අනිත්‍ය බව සිහිපත් කරන නිශ්චල ජීව චිත්‍ර වර්ගය කුමක්ද?", "වැනිටාස් සංකේත නිශ්චල චිත්‍ර", "ගංගා හා කඳු භූ දර්ශන සිතුවම්", "රාජ සභා මංගල උත්සව සිතුවම්", "නාගරික වෙළඳපොළ දර්ශන", "ධනවත් වෙළෙඳුන්ට ලෞකික සැපයේ කෙටිකාලීන බව සිහිගැන්වීමට සංකේතාත්මක වස්තු සිතුවම් කළහ."),
        q("බැරොක් යුගයේ රෝමයේ පාප්තුමාගේ අනුග්‍රහයෙන් 'ශාන්ත පීතර චතුරස්‍රයේ' අලංකාර කුළුණු පෙළ (Colonnade) නිර්මාණය කළේ කවුද?", "ජියන් ලොරෙන්සෝ බර්නිනි (Bernini)", "ලියනාඩෝ ඩා වින්චි", "ෆිලිප්පෝ බෘනෙලෙස්කි", "වින්සන්ට් වෑන් ගෝ", "වන්දනාකරුවන් වැළඳගන්නා දෑත් දෙකක් මෙන් අර්ධ වෘත්තාකාර කුළුණු මාලාව බර්නිනි සැලසුම් කළේය."),
        q("ඉතාලි බැරොක් සිතුවම් කලාවේ සුප්‍රකට කාන්තා චිත්‍ර ශිල්පිනියක වන 'ආටෙමීසියා ජෙන්ටිලෙස්කි' (Artemisia Gentileschi) ප්‍රකට වන්නේ කුමක් සඳහාද?", "තියුණු ආලෝකයෙන් බයිබල් කාන්තාවන්", "සියුම් ජල සායම් මල් කළඹ", "වියුක්ත ජ්‍යාමිතික කළු කොටු", "මැටි පිළිස්සූ කුඩා ප්‍රතිමා", "'හොලොෆර්නස් ඝාතනය කරන ජුඩිත්' වැනි ප්‍රබල සිතුවම් හරහා ඇය බැරොක් ඉතිහාසයේ ප්‍රධාන තැනක් ගනී."),
        q("රේඛීය දෘෂ්ටිකෝණයට අමතරව දුර ඇති කඳු හා ගස් ලා නිල්-අළු පැහැයෙන් අඳුරු නැතිව ඇඳ ගැඹුර මවන පුනරුද ශිල්පය කුමක්ද?", "වායුගෝලීය දෘෂ්ටිකෝණය", "ඒකලක්ෂ්‍ය ජ්‍යාමිතික රේඛා", "රන් පසුබිම් මොසැයික් රටාව", "තද කළු බාහිර සමෝච්ඡ රේඛාව", "ලියනාඩෝ ඩා වින්චි මොනාලිසා පසුබිමේ කඳු පෙළ සඳහා මෙම වායුගෝලීය බොඳවීම අපූරුවට යොදා ගත්තේය."),
        q("17 වන සියවසේ ප්‍රංශයේ 14 වන ලුවී රජු විසින් ඉදි කළ දැවැන්ත බැරොක්-සම්භාව්‍ය රාජ මාලිගය හා කැඩපත් ශාලාව (Hall of Mirrors) ඇත්තේ කොහේද?", "වර්සේල්ස් රාජ මාලිගයේ", "රෝමයේ කොලෝසියමේ", "ලූවර් පිරමීඩ ශාලාවේ", "පැන්තියන් දේවාලයේ", "රන් ආලේපිත බිත්ති, චැන්ඩිලියර් පහන් හා ජ්‍යාමිතික උද්‍යාන වර්සේල්ස්හි රාජකීය තේජස පෙන්වයි."),
        q("බටහිර චිත්‍ර කලාවේ 'ටෙම්පරා' (Egg Tempera) මාධ්‍යයේදී වර්ණ කුඩු කැන්වසයට හෝ ලී පුවරුවට ඇලවීමට යොදාගත් ස්වභාවික බන්ධකය කුමක්ද?", "බිත්තර කහ මදය (Egg Yolk)", "සාමාන්‍ය රබර් කිරි", "පෙට්‍රල් සහ ග්‍රීස්", "සීනි පැණි", "තෙල් සායම් ජනප්‍රිය වීමට පෙර බොටිචෙලි හා ජොටෝ වැනි ශිල්පීහු බිත්තර කහ මදයෙන් සැදූ ටෙම්පරා භාවිත කළහ."),
        q("16 වන සියවසේ සිට 19 වන සියවස දක්වා යුරෝපීය කලා ඇකඩමිවල වඩාත්ම උසස් කලා විෂය ධාරාව (Hierarchy of Genres) ලෙස සැලකුවේ කුමක්ද?", "ඓතිහාසික හා ආගමික සිතුවම්", "පලතුරු බඳුන් නිශ්චල සිතුවම්", "වීදි හා ගැමි ජීවිත සිතුවම්", "වියුක්ත රේඛා සටහන් චිත්‍ර", "විශාල ඓතිහාසික හා ආගමික සංයුති ඉහළින්මද, ආලේඛ්‍ය, භූ දර්ශන හා නිශ්චල චිත්‍ර පිළිවෙළින් පහළින්ද තැබීය."),
        q("පුනරුද යුගයේ රැෆායෙල් විසින් භාවිත කළ 'පිරමීඩ හෙවත් ත්‍රිකෝණාකාර සංයුතිය' (Pyramidal Composition) සිතුවමට ලබා දෙන ගුණය කුමක්ද?", "ස්ථාවරත්වය හා සමබරතාව", "චලනයේ අස්ථාවර හැඟීම", "රූප අසාමාන්‍ය ලෙස විකෘති වීම", "අවකාශය මුළුමනින්ම වැසී යාම", "රැෆායෙල්ගේ 'මැඩෝනා' සිතුවම්වල රූප පිරමීඩයක් සේ පිහිටුවා සන්සුන් සමතුලිතතාවක් රැක ගනී."),
        q("බැරොක් යුගයේ චිත්‍ර ශිල්පීන් රැසක් භාවිත කළ 'ඉම්පැස්ටෝ' (Impasto) ශිල්පීය ක්‍රමය යනු කුමක්ද?", "තෙල් සායම් ඝනව තැවරීම", "වර්ණ ස්තර ජලයෙන් සේදීම", "පැන්සලෙන් සියුම් ඉරි ගැසීම", "ලෝහ තහඩුවකින් මුද්‍රණය කිරීම", "රෙම්බ්‍රාන්ට් හා පසුව වෑන් ගෝ ඝන තීන්ත ස්තර මගින් ආලෝකය පරාවර්තනය වන ගැටිති මතුපිට මැවූහ."),
        q("පුරාණ රෝමවරුන් විසින් ජනතාවගේ දැනුම හා ජල සැපයුම වෙනුවෙන් ආරුක්කු පේළි මත ඉදි කළ අලංකාර වාස්තු නිර්මාණය කුමක්ද?", "ජල මාර්ග පාලම් (Aqueducts)", "ගෝලාකාර වහල දෙව්මැදුරු", "උල් ආරුක්කු පල්ලි", "පියගැට පිරමීඩ", "ගල් ආරුක්කු මහල් කිහිපයක් මත සැතපුම් ගණන් ජලය ගෙන ගිය රෝම ඇක්විඩක්ට් පාලම් කලාත්මක ඉදිකිරීම් වේ."),
        q("19 වන සියවසේ ප්‍රංශ යථාර්ථවාදී චිත්‍ර ශිල්පී 'ඔනෝරේ දෝමියේ' (Honoré Daumier) බොහෝ විට සිතුවම් කළේ කුමන මාධ්‍යයෙන් හා අරමුණකින්ද?", "ලිතොග්‍රැෆි සමාජ උපහාස චිත්‍ර", "රාජකීය ආලේඛ්‍ය තෙල් සායම්", "බිතුසිතුවම් ආගමික සැරසිලි", "ලෝකඩ මූර්ති නිර්මාණය", "අධිකරණ, දුම්රිය මැදිරි හා පොදු ජන පීඩනය දෝමියේ තියුණු රේඛාවෙන් හෙළිදරව් කළේය."),
        q("රොමෑන්ටික් යුගයේ ප්‍රංශ ශිල්පී 'තියඩෝර් ජෙරිකෝ' (Théodore Géricault) නිර්මාණය කළ නාවික ඛේදවාචකය දක්වන මහා සිතුවම කුමක්ද?", "මෙඩුසා පහුර (Raft of Medusa)", "මොනාලිසා ආලේඛ්‍යය", "ගුවර්නිකා සිතුවම", "වීනස්ගේ උපත සිතුවම", "මුහුදේ අතරමං වූ නාවිකයන්ගේ බලාපොරොත්තුව හා බලාපොරොත්තු සුන්වීම විකර්ණ ත්‍රිකෝණ දෙකකින් පෙන්වයි."),
        q("නව-සම්භාව්‍යවාදී චිත්‍ර ශිල්පී 'ජීන්-ඔගස්ට්-ඩොමිනික් ඉන්ග්‍රේ' (Ingres) සිතුවම්වල කැපී පෙනුණු ගුණාංගය කුමක්ද?", "සිනිඳු වර්ණ හා පිරිසිදු රේඛාව", "ඝන රළු තීන්ත පැල්ලම්", "විකෘති වූ කියුබිස්ට් හැඩ", "කළු අඟුරු කෙටුම්පත් පමණක්", "ඩෙලාක්‍රොයික්ස්ගේ වර්ණවාදයට ප්‍රතිවිරුද්ධව ඉන්ග්‍රේ රේඛාවේ පරිපූර්ණත්වය අගය කළේය."),
        q("බටහිර සම්භාව්‍ය කලාවේ මිසර යුගයේ සිට රොමෑන්ටික් යුගය දක්වා සිදු වූ ප්‍රධාන ශෛලිමය වෙනස කුමක්ද?", "සම්ප්‍රදායෙන් හැඟීම් ප්‍රකාශනයට", "සම්පූර්ණයෙන් පැතලි කූරු රූප දක්වා", "වර්ණ භාවිතය සම්පූර්ණයෙන් අතහැරීම", "ගල් කැටයම් පමණක් ඉතිරි වීම", "19 වන සියවස අග වන විට ඡායාරූප කැමරාවේ පැමිණීමත් සමඟ බටහිර කලාව නූතනවාදී වෙනසකට යොමු විය."),
        q("බටහිර පුනරුද යුගයේ දැවැන්ත චිත්‍ර ශිල්පීන් බහුලව භාවිත කළ 'ගෝල්ඩන් රේෂියෝ' (Golden Ratio - 1:1.618) සංකල්පය කුමක් සඳහා උපකාරී වූවාද?", "සමබර හා ස්වභාවික අනුපාත සඳහා", "වර්ණ කුඩු බර කිරා ගැනීමට", "පින්සල් සේදීමේ දියර මැනීමට", "රාමු මිල නියම කිරීම සඳහා", "පාතිනන් දේවාලයේ සිට මොනාලිසා දක්වා ස්වභාවධර්මයේ මෙම රන්මය අනුපාතය සමබරතාව සඳහා යොදා ගනී."),
        q("පුරාණ ග්‍රීක හා රෝම යුගවල ප්‍රතිමා පිළිබඳව අද බොහෝ දෙනා වරදවා වටහා ගන්නා ඓතිහාසික සත්‍යය කුමක්ද?", "පුරාණයේදී ඒවා වර්ණ ගන්වා තිබුණි", "ඒවා මැටිවලින් පමණක් තැනීය", "ග්‍රීකයන් මූර්ති කලාව නොකළේය", "ඒවා කළු තාරවලින් වසා තිබුණි", "පුරාවිද්‍යාත්මක පරීක්ෂණවලින් පාතිනන් හා රෝම මූර්තිවල වර්ණ අංශු හමුවී ඇත."),
        q("රෙම්බ්‍රාන්ට් හා ඩියුරර් වැනි යුරෝපීය ශිල්පීන් ප්‍රගුණ කළ 'එචිං' (Etching) මුද්‍රණ කලාවේදී ලෝහ තහඩුවේ රේඛා හාරන්නේ කෙසේද?", "ඇසිඩ් ද්‍රාවණයකින් විඛාදනයෙන්", "තියුණු පිහියකින් ලී කැපීමෙන්", "තෙත් මැටි පුවරු ඇලවීමෙන්", "පින්සලෙන් තීන්ත බින්දු ඉසීමෙන්", "ඉන්ටග්ලියෝ මුද්‍රණ ක්‍රමයක් වන එචිං මගින් ඉතා සියුම් රේඛා දහස් ගණනක් කඩදාසියට මුද්‍රණය කළ හැකිය."),
        q("17 වන සියවසේ ප්‍රංශයේ සම්භාව්‍ය භූ දර්ශන සිතුවම්කරණයේ පුරෝගාමීන් වූ නිකොලාස් පූසන් (Poussin) සහ ක්ලෝඩ් ලොරේන් අවධාරණය කළේ කුමක්ද?", "පරමාදර්ශී භූ දර්ශන හා හිරු එළිය", "කාර්මික කම්හල් සහ දුම් නළ", "ප්‍රාග් ඓතිහාසික ගල් ගුහා", "වියුක්ත ජ්‍යාමිතික තිත් රටා", "සොබාදහමේ ගැඹුරු සන්සුන් අලංකාරය කැන්වසය මත සංවිධානාත්මකව ගොඩනැගීම ඔවුන්ගේ ශෛලියයි."),
        q("බටහිර කලාවේ 'මධ්‍යකාලීන අත්පිටපත් ආලෝකකරණය' (Illuminated Manuscripts) යනු කුමක්ද?", "රන් පත්‍ර හා සිතුවමින් පොත් සැරසීම", "වීදුරු ආරුක්කු කවුළු නිර්මාණය", "මැටි පුවරුවල අකුරු කෙටීම", "කැන්වස් මත තෙල් සායම් සිතුවම්", "මුද්‍රණ යන්ත්‍රයට පෙර කෙල්ටික් හා ගොතික් තාපසාරාමවල බුක් ඔෆ් කෙල්ස් වැනි අනර්ඝ පොත් සිතුවම් කෙරිණි."),
        q("රෝමයේ ක්‍රිස්තියානි කලාවේ මුල් අවදියේ භූගත සොහොන් උමං බිත්තිවල ඇඳි මුල් කිතුනු සිතුවම් හමුවන්නේ කොහෙන්ද?", "කැටකොම්බ්ස් (Catacombs) උමං", "පාතිනන් දේවාල වහලය", "ගීසා මහා පිරමීඩය", "වර්සේල්ස් මාලිගය", "රෝම පීඩන සමයේ මුල් කිතුනුවන් යහපත් එඬේරා හා මත්ස්‍ය සංකේත කැටකොම්බ්ස් බිත්තිවල ඇඳ තිබුණි."),
        q("ඉතාලි පුනරුද මූර්ති කලාවේ පියවරක් වූ 'රොමේනියානු හා මධ්‍යකාලීන' සිරුරු වසා දැමීම වෙනුවට මයිකල් ආන්ජලෝ ප්‍රතිමා නෙළීමේදී දැරූ දර්ශනය කුමක්ද?", "පාෂාණය තුළ සිරවූ රුව මුදා ගැනීම", "කැඩුණු මැටි කැබලි එකට ඇලවීම", "රන් කඩදාසි මත පිළිම වැසීම", "සරල ජ්‍යාමිතික රේඛා කැපීම", "කිරිගරුඬ පාෂාණය තුළ ජීවත් වන මිනිස් ස්වරූපය අමතර ගල් කපා ඉවත් කර මතු කරන බව ඔහු පැවසීය."),
        q("19 වන සියවසේ බ්‍රිතාන්‍යයේ කාර්මික විප්ලවයට විරෝධය පා අතින් කළ සැරසිලි හා මධ්‍යකාලීන සිහින ලෝක අගය කළ ව්‍යාපාරය කුමක්ද?", "ප්‍රී-රැෆායෙලයිට් සහෝදරත්වය", "විශ්ලේෂණාත්මක කියුබිසම් ව්‍යාපාරය", "නූතන පොප් කලා ව්‍යාපාරය", "පළමු ඩාඩාවාදී ව්‍යාපාරය", "විලියම් හොල්මන් හන්ට්, රොසෙටි හා මිලේයිස් ඉතා දීප්තිමත් වර්ණ හා සියුම් ස්වභාවික විස්තර සිතුවම් කළහ."),
        q("සම්භාව්‍ය බටහිර චිත්‍ර කලාවේ සුප්‍රකට 'ගැඹුර හා අවකාශය' නිර්මාණය කිරීමට භාවිත කළ ප්‍රධාන උපක්‍රම තුන කවරේද?", "අතිපිහිටීම, ප්‍රමාණය, දෘෂ්ටිකෝණය", "රතු පසුබිම, කළු ඉර, පලාපෙති", "පැතලි වර්ණ, තිත් සහ හිස්බව", "මුද්‍රා තැබීම, කැපීම, ඇලවීම", "ත්‍රිමාණ මායාව කැන්වසයේ ද්විමාන තලය මත මවා පෑමට මෙම රීති අත්‍යවශ්‍ය විය.")
    )
}
